function previewSale(){const box=document.getElementById('salePreview');if(!box)return;const product=document.getElementById('saleProduct')?.value.trim(),r=allRecipes().find(x=>String(x.name||'').trim().toLowerCase()===product.toLowerCase());const q=Number(document.getElementById('saleQty')?.value||1),p=Number(document.getElementById('salePrice')?.value||0),d=Number(document.getElementById('saleDiscount')?.value||0),c=Number(document.getElementById('saleCommission')?.value||0),card=Number(document.getElementById('saleCard')?.value||0);const gross=p*q,disc=gross*d/100,net=gross-disc-(gross-disc)*c/100-card,cost=r?recipeCostDetail(r).cost/Math.max(1,Number(r.yieldQty||1))*q:0;box.innerHTML=`Bruto <b>${money(gross)}</b> · Descuento <b>${money(disc)}</b> · Neto <b>${money(net)}</b> · Costo <b>${money(cost)}</b> · Utilidad <b>${money(net-cost)}</b>`}
