function recipeCostDetail(r){
 const items=Array.isArray(r?.items)?r.items:[];
 if(!items.length){return {cost:Number(r?.cost||0),source:'IMPORTADO',missing:[],lines:[]}}
 let total=0;const missing=[];const lines=[];
 for(const item of items){
  const product=(master.products||[]).find(p=>(item.productId&&p.id===item.productId)||String(p.name||'').trim().toLowerCase()===String(item.ingredient||item.product||'').trim().toLowerCase());
  if(!product){missing.push(item.ingredient||item.product||'Ingrediente');lines.push({...item,cost:0,missing:true});continue}
  try{const c=window.LRXCost.lineCost(product,Number(item.qty||0),item.unit||product.standardUnit||product.unit||'unit');total+=c;lines.push({...item,productId:product.id,cost:c,missing:false})}
  catch(e){missing.push(item.ingredient||item.product||product.name);lines.push({...item,productId:product.id,cost:0,missing:true,error:e.message})}
 }
 if(missing.length&&Number(r?.cost||0)>0)return {cost:Number(r.cost),source:'IMPORTADO · REVISAR',missing,lines};
 return {cost:total,source:missing.length?'INCOMPLETO':'ACTUAL',missing,lines};
}
