 const costed=rows.filter(r=>r.d.cost>0).length,withPrice=rows.filter(r=>r.price>0),avg=withPrice.length?withPrice.reduce((a,r)=>a+r.fc,0)/withPrice.length:0;
 return head('Food Cost','Costeo operativo por receta usando el costo utilizable de SUP.',`<div class="toolbar"><input id="fcSearch" class="input search" placeholder="Buscar receta..."><label class="inlinefield">Food Cost objetivo % <input id="fcTarget" class="input" type="number" min="1" max="100" step="0.1" value="${target}"></label><button class="btn" data-action="apply-fc-target">Aplicar</button><button class="btn" data-action="export-foodcost">Exportar CSV</button></div>`)+
 `<div class="grid"><div class="card kpi"><small>Recetas</small><strong>${rows.length}</strong></div><div class="card kpi"><small>Con costo</small><strong>${costed}</strong></div><div class="card kpi"><small>Food Cost promedio</small><strong>${avg.toFixed(1)}%</strong></div><div class="card kpi"><small>Objetivo</small><strong>${target.toFixed(1)}%</strong></div></div>`+
 `<div class="card" style="margin-top:14px"><div class="tablewrap"><table><thead><tr><th>Receta</th><th>Precio</th><th>Costo/u</th><th>Food Cost</th><th>Precio objetivo</th><th>Utilidad/u</th><th>Margen</th><th>Origen</th></tr></thead><tbody id="foodcostRows">${rows.map(r=>{const profit=r.price-r.cu,margin=r.price?profit/r.price*100:0;return `<tr data-search="${esc(String(r.name).toLowerCase())}"><td><b>${esc(r.name)}</b><small class="muted">${esc(r.yield||r.yieldQty||1)} ${esc(r.yieldUnit||'')}</small></td><td>${r.price?money(r.price):'—'}</td><td>${money(r.cu)}</td><td>${r.price?r.fc.toFixed(1)+'%':'—'}</td><td>${money(r.targetPrice)}</td><td>${r.price?money(profit):'—'}</td><td>${r.price?margin.toFixed(1)+'%':'—'}</td><td><span class="status">${esc(r.d.source)}</span>${r.d.missing.length?`<small class="muted">Faltan: ${esc(r.d.missing.slice(0,2).join(', '))}${r.d.missing.length>2?'…':''}</small>`:''}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">No hay recetas.</td></tr>'}</tbody></table></div></div>`;
